/// Families in catalogue order, each with its light/dark members.
export interface KbcThemeFamily {
  readonly family: string;
  readonly familyName: string;
  readonly members: readonly KbcThemeEntry[];
}

export const KBC_THEME_FAMILIES: readonly KbcThemeFamily[] = (() => {
  const out: KbcThemeFamily[] = [];
  for (const t of KBC_THEMES) {
    let fam = out.find((f) => f.family === t.family);
    if (!fam) {
      fam = { family: t.family, familyName: t.familyName, members: [] };
      out.push(fam);
    }
    (fam.members as KbcThemeEntry[]).push(t);
  }
  return out;
})();
